00070     private function getServiceShutdownOrder()
00071     {
00072         // Define shutdown order: dependent services first, then core services
00073         // This prevents connection errors and ensures clean shutdown
00074         return [
00075             // Tier 1: Application services (no dependencies on other services)
00076             BinMailpit::SERVICE_NAME,      // Mail testing tool
00077             BinMemcached::SERVICE_NAME,    // Caching service
00078             BinXlight::SERVICE_NAME,       // FTP server
00079 
00080             // Tier 2: Database services (web server depends on these)
00081             BinPostgresql::SERVICE_NAME,   // PostgreSQL database
00082             BinMariadb::SERVICE_NAME,      // MariaDB database
00083             BinMysql::SERVICE_NAME,        // MySQL database
00084 
00085             // Tier 3: Web server (depends on databases and other services)
00086             BinApache::SERVICE_NAME,       // Apache web server (stopped last)
00087         ];
00088     }
