00110             $name = $bearsamppBins->getMailpit()->getName() . ' ' . $bearsamppBins->getMailpit()->getVersion();
00111         }
00112         elseif ($sName == BinMariadb::SERVICE_NAME) {
00113             $name = $bearsamppBins->getMariadb()->getName() . ' ' . $bearsamppBins->getMariadb()->getVersion();
00114         }
00115         elseif ($sName == BinPostgresql::SERVICE_NAME) {
00116             $name = $bearsamppBins->getPostgresql()->getName() . ' ' . $bearsamppBins->getPostgresql()->getVersion();
00117         }
00118         elseif ($sName == BinMemcached::SERVICE_NAME) {
00119             $name = $bearsamppBins->getMemcached()->getName() . ' ' . $bearsamppBins->getMemcached()->getVersion();
