00139     public function processWindow($window, $id, $ctrl, $param1, $param2)
00140     {
00141         global $bearsamppBins, $bearsamppLang, $bearsamppWinbinder;
00142 
00143         Log::info('Starting graceful shutdown process with optimized service order');
00144 
00145         // Get all available services
00146         $allServices = $bearsamppBins->getServices();
00147 
00148         // Get optimal shutdown order
00149         $shutdownOrder = $this->getServiceShutdownOrder();
00150 
00151         Log::debug('Service shutdown order: ' . implode(' -> ', $shutdownOrder));
00152 
00153         // Stop services in optimal order
00154         foreach ($shutdownOrder as $sName) {
00155             // Check if this service exists and is installed
00156             if (!isset($allServices[$sName])) {
00157                 Log::debug('Service not found in available services: ' . $sName);
00158                 continue;
00159             }
00160 
00161             $service = $allServices[$sName];
00162             $displayName = $this->getServiceDisplayName($sName, $service);
00163 
00164             Log::info('Stopping service: ' . $displayName);
00165 
00166             $this->splash->incrProgressBar();
00167             $this->splash->setTextLoading(sprintf($bearsamppLang->getValue(Lang::EXIT_REMOVE_SERVICE_TEXT), $displayName));
00168 
00169             // Delete (stop and remove) the service
00170             $result = $service->delete();
00171 
00172             if ($result) {
00173                 Log::info('Successfully stopped and removed service: ' . $displayName);
00174             } else {
00175                 Log::warning('Failed to stop/remove service: ' . $displayName . ' (may not be installed)');
00176             }
00177         }
00178 
00179         // Handle any services not in the shutdown order (for extensibility)
00180         foreach ($allServices as $sName => $service) {
00181             if (!in_array($sName, $shutdownOrder)) {
00182                 $displayName = $this->getServiceDisplayName($sName, $service);
00183                 Log::warning('Stopping unlisted service: ' . $displayName);
00184 
00185                 $this->splash->incrProgressBar();
00186                 $this->splash->setTextLoading(sprintf($bearsamppLang->getValue(Lang::EXIT_REMOVE_SERVICE_TEXT), $displayName));
00187                 $service->delete();
00188             }
00189         }
00190 
00191         Log::info('All services stopped successfully');
00192 
00193         // Purge "current" symlinks
00194         $this->splash->setTextLoading('Removing symlinks...');
00195         Symlinks::deleteCurrentSymlinks();
00196 
00197         // Stop other processes
00198         $this->splash->incrProgressBar();
00199         $this->splash->setTextLoading($bearsamppLang->getValue(Lang::EXIT_STOP_OTHER_PROCESS_TEXT));
00200         Win32Ps::killBins(true);
00201 
00202         // Explicitly kill NodeJS if still running (it's not a Windows service)
00203         Log::trace('Explicitly terminating NodeJS processes');
00204         Win32Ps::killBins(['node.exe']);
00205 
00206         // Perform cleanup verification in background (non-blocking)
00207         $this->splash->setTextLoading('Performing cleanup verification...');
00208         $this->performQuickCleanupVerification($allServices);
00209 
00210         // Terminate any remaining processes
00211         // Final termination sequence
00212         $this->splash->setTextLoading('Completing shutdown...');
00213         if (strtoupper(substr(PHP_OS, 0, 3)) === 'WIN') {
00214             $currentPid = Win32Ps::getCurrentPid();
00215 
00216             // Terminate PHP processes with a timeout of 15 seconds
00217             self::terminatePhpProcesses($currentPid, $window, $this->splash, 15);
00218 
00219             // Force exit if still running
00220             exit(0);
00221         }
00222 
00223         // Non-Windows fallback
00224         $bearsamppWinbinder->destroyWindow($window);
00225         exit(0);
00226     }
