00237     public static function terminatePhpProcesses($excludePid, $window = null, $splash = null, $timeout = 10)
00238     {
00239         global $bearsamppWinbinder, $bearsamppCore;
00240 
00241         $currentPid = Win32Ps::getCurrentPid();
00242         $startTime = microtime(true);
00243 
00244         Log::trace('Starting PHP process termination (excluding PID: ' . $excludePid . ')');
00245 
00246         // Get list of loading PIDs to exclude from termination
00247         $loadingPids = array();
00248         if (file_exists($bearsamppCore->getLoadingPid())) {
00249             $pids = file($bearsamppCore->getLoadingPid());
00250             foreach ($pids as $pid) {
00251                 $loadingPids[] = intval(trim($pid));
00252             }
00253             Log::trace('Loading PIDs to preserve: ' . implode(', ', $loadingPids));
00254         }
00255 
00256         $targets = ['php-win.exe', 'php.exe'];
00257         foreach (Win32Ps::getListProcs() as $proc) {
00258             // Check if we've exceeded our timeout
00259             if (microtime(true) - $startTime > $timeout) {
00260                 Log::trace('Process termination timeout exceeded, continuing with remaining operations');
00261                 break;
00262             }
00263 
00264             $exe = strtolower(basename($proc[Win32Ps::EXECUTABLE_PATH]));
00265             $pid = $proc[Win32Ps::PROCESS_ID];
00266 
00267             // Skip if this is the excluded PID or a loading window PID
00268             if (in_array($exe, $targets) && $pid != $excludePid && !in_array($pid, $loadingPids)) {
00269                 Log::trace('Terminating PHP process: ' . $pid);
00270                 Win32Ps::kill($pid);
00271                 usleep(100000); // 100ms delay between terminations
00272             } elseif (in_array($pid, $loadingPids)) {
00273                 Log::trace('Preserving loading window process: ' . $pid);
00274             }
00275         }
00276 
00277         // Initiate self-termination with timeout
00278         if ($splash !== null) {
00279             $splash->setTextLoading('Final cleanup...');
00280         }
00281 
00282         try {
00283             Log::trace('Initiating self-termination for PID: ' . $currentPid);
00284             // Add a timeout wrapper around the killProc call
00285             $killSuccess = Win32Native::killProcess($currentPid);
00286             if (!$killSuccess) {
00287                 Log::trace('Self-termination via Win32Native::killProcess failed, using alternative method');
00288             }
00289         } catch (\Exception $e) {
00290             Log::trace('Exception during self-termination: ' . $e->getMessage());
00291         }
00292 
00293         // Destroy window after process termination
00294         // Fix for PHP 8.2: Check if window is not null before destroying
00295         if ($window && $bearsamppWinbinder) {
00296             try {
00297                 Log::trace('Destroying window');
00298                 $bearsamppWinbinder->destroyWindow($window);
00299             } catch (\Exception $e) {
00300                 Log::trace('Exception during window destruction: ' . $e->getMessage());
00301             }
00302         }
00303 
00304         // Force exit if still running after timeout
00305         if (microtime(true) - $startTime > $timeout * 1.5) {
00306             Log::trace('Forcing exit due to timeout');
00307             exit(0);
00308         }
00309     }
