00317     private function verifyServicesStoppedAndCleanup($services)
00318     {
00319         Log::info('Verifying all services are stopped...');
00320 
00321         $results = [
00322             'all_stopped' => true,
00323             'services' => [],
00324             'still_running' => [],
00325             'verification_failed' => []
00326         ];
00327 
00328         foreach ($services as $sName => $service) {
00329             $displayName = $this->getServiceDisplayName($sName, $service);
00330 
00331             try {
00332                 // Check if service is still installed/running
00333                 $isInstalled = $service->isInstalled();
00334                 $isRunning = $isInstalled ? $service->isRunning() : false;
00335 
00336                 $results['services'][$sName] = [
00337                     'name' => $displayName,
00338                     'installed' => $isInstalled,
00339                     'running' => $isRunning
00340                 ];
00341 
00342                 if ($isRunning) {
00343                     Log::warning('Service still running after shutdown: ' . $displayName);
00344                     $results['still_running'][] = $displayName;
00345                     $results['all_stopped'] = false;
00346 
00347                     // Attempt to force stop
00348                     Log::info('Attempting to force stop: ' . $displayName);
00349                     $service->stop();
00350                     usleep(500000); // Wait 500ms
00351 
00352                     // Verify again
00353                     if ($service->isRunning()) {
00354                         Log::error('Failed to force stop service: ' . $displayName);
00355                     } else {
00356                         Log::info('Successfully force stopped service: ' . $displayName);
00357                     }
00358                 } elseif ($isInstalled) {
00359                     Log::debug('Service stopped but still installed: ' . $displayName);
00360                 } else {
00361                     Log::debug('Service verified stopped and removed: ' . $displayName);
00362                 }
00363 
00364             } catch (\Exception $e) {
00365                 Log::error('Failed to verify service status for ' . $displayName . ': ' . $e->getMessage());
00366                 $results['verification_failed'][] = $displayName;
00367                 $results['all_stopped'] = false;
00368             }
00369         }
00370 
00371         if ($results['all_stopped']) {
00372             Log::info('All services verified stopped successfully');
00373         } else {
00374             Log::warning('Some services could not be verified as stopped');
00375         }
00376 
00377         return $results;
00378     }
