00385     private function verifySymlinksRemoved()
00386     {
00387         global $bearsamppRoot;
00388 
00389         Log::info('Verifying symlinks are removed...');
00390 
00391         $results = [
00392             'success' => true,
00393             'remaining' => []
00394         ];
00395 
00396         // Check common symlink locations
00397         $symlinkPaths = [
00398             Path::getRootPath() . '/apache',
00399             Path::getRootPath() . '/php',
00400             Path::getRootPath() . '/mysql',
00401             Path::getRootPath() . '/mariadb',
00402             Path::getRootPath() . '/postgresql',
00403             Path::getRootPath() . '/nodejs',
00404             Path::getRootPath() . '/memcached',
00405             Path::getRootPath() . '/mailpit',
00406             Path::getRootPath() . '/xlight'
00407         ];
00408 
00409         foreach ($symlinkPaths as $path) {
00410             if (file_exists($path) || is_link($path)) {
00411                 Log::warning('Symlink still exists: ' . $path);
00412                 $results['remaining'][] = basename($path);
00413                 $results['success'] = false;
00414 
00415                 // Attempt to remove it using robust method
00416                 try {
00417                     $removed = \Symlinks::safeRemoveSymlink($path);
00418 
00419                     // Verify removal
00420                     if ($removed && !file_exists($path) && !is_link($path)) {
00421                         Log::info('Successfully removed remaining symlink: ' . $path);
00422                         $results['remaining'] = array_diff($results['remaining'], [basename($path)]);
00423                         if (empty($results['remaining'])) {
00424                             $results['success'] = true;
00425                         }
00426                     }
00427                 } catch (\Exception $e) {
00428                     Log::error('Failed to remove symlink ' . $path . ': ' . $e->getMessage());
00429                 }
00430             }
00431         }
00432 
00433         if ($results['success']) {
00434             Log::info('All symlinks verified removed');
00435         } else {
00436             Log::warning('Some symlinks could not be removed: ' . implode(', ', $results['remaining']));
00437         }
00438 
00439         return $results;
00440     }
