00447     private function cleanupTemporaryFiles()
00448     {
00449         global $bearsamppCore;
00450 
00451         Log::info('Cleaning up temporary files...');
00452 
00453         $results = [
00454             'success' => true,
00455             'cleaned' => 0,
00456             'failed' => [],
00457             'size_freed' => 0
00458         ];
00459 
00460         $tmpPath = Path::getTmpPath();
00461 
00462         if (!is_dir($tmpPath)) {
00463             Log::debug('Temp directory does not exist: ' . $tmpPath);
00464             return $results;
00465         }
00466 
00467         try {
00468             $files = glob($tmpPath . '/*');
00469 
00470             if ($files === false) {
00471                 Log::warning('Failed to list temporary files');
00472                 return $results;
00473             }
00474 
00475             foreach ($files as $file) {
00476                 // Skip certain files that should be preserved
00477                 $basename = basename($file);
00478                 if (in_array($basename, ['.', '..', '.gitkeep', 'README.md'])) {
00479                     continue;
00480                 }
00481 
00482                 try {
00483                     $size = is_file($file) ? filesize($file) : 0;
00484 
00485                     if (is_link($file)) {
00486                         if (@unlink($file) || @rmdir($file)) {
00487                             $results['cleaned']++;
00488                             $results['size_freed'] += $size;
00489                             Log::debug('Removed temp symlink: ' . $basename);
00490                         } else {
00491                             $results['failed'][] = $basename;
00492                             $results['success'] = false;
00493                             Log::warning('Failed to remove temp symlink: ' . $basename);
00494                         }
00495                     } elseif (is_file($file)) {
00496                         if (@unlink($file)) {
00497                             $results['cleaned']++;
00498                             $results['size_freed'] += $size;
00499                             Log::debug('Removed temp file: ' . $basename);
00500                         } else {
00501                             $results['failed'][] = $basename;
00502                             $results['success'] = false;
00503                             Log::warning('Failed to remove temp file: ' . $basename);
00504                         }
00505                     } elseif (is_dir($file)) {
00506                         Util::deleteFolder($file);
00507                         if (!file_exists($file)) {
00508                             $results['cleaned']++;
00509                             Log::debug('Removed temp directory: ' . $basename);
00510                         } else {
00511                             $results['failed'][] = $basename;
00512                             $results['success'] = false;
00513                             Log::warning('Failed to remove temp directory: ' . $basename);
00514                         }
00515                     }
00516                 } catch (\Exception $e) {
00517                     $results['failed'][] = $basename;
00518                     $results['success'] = false;
00519                     Log::error('Error removing temp file ' . $basename . ': ' . $e->getMessage());
00520                 }
00521             }
00522 
00523             $sizeMB = round($results['size_freed'] / 1024 / 1024, 2);
00524             Log::info('Cleaned up ' . $results['cleaned'] . ' temporary files (' . $sizeMB . ' MB freed)');
00525 
00526             if (!empty($results['failed'])) {
00527                 Log::warning('Failed to clean up ' . count($results['failed']) . ' files');
00528             }
00529 
00530         } catch (\Exception $e) {
00531             Log::error('Error during temp file cleanup: ' . $e->getMessage());
00532             $results['success'] = false;
00533         }
00534 
00535         return $results;
00536     }
