00543     private function checkForOrphanedProcesses()
00544     {
00545         global $bearsamppRoot;
00546 
00547         Log::info('Checking for orphaned processes...');
00548 
00549         $orphaned = [
00550             'found' => false,
00551             'processes' => []
00552         ];
00553 
00554         try {
00555             $procs = Win32Ps::getListProcs();
00556             $bearsamppPath = strtolower(Path::formatUnixPath(Path::getRootPath()));
00557             $currentPid = Win32Ps::getCurrentPid();
00558 
00559             foreach ($procs as $proc) {
00560                 $exePath = strtolower(Path::formatUnixPath($proc[Win32Ps::EXECUTABLE_PATH]));
00561                 $pid = $proc[Win32Ps::PROCESS_ID];
00562 
00563                 // Skip current process
00564                 if ($pid == $currentPid) {
00565                     continue;
00566                 }
00567 
00568                 // Check if process is from Bearsampp directory
00569                 if (strpos($exePath, $bearsamppPath) === 0) {
00570                     $processName = basename($exePath);
00571 
00572                     // Skip www directory processes (user applications)
00573                     if (strpos($exePath, $bearsamppPath . '/www/') === 0) {
00574                         continue;
00575                     }
00576 
00577                     // Skip the main Bearsampp executable
00578                     if (strtolower($processName) === 'bearsampp.exe') {
00579                         Log::debug('Skipping main Bearsampp process: ' . $processName . ' (PID: ' . $pid . ')');
00580                         continue;
00581                     }
00582 
00583                     // These are orphaned Bearsampp processes
00584                     $orphaned['found'] = true;
00585                     $orphaned['processes'][] = [
00586                         'pid' => $pid,
00587                         'name' => $processName,
00588                         'path' => $exePath
00589                     ];
00590 
00591                     Log::warning('Found orphaned process: ' . $processName . ' (PID: ' . $pid . ')');
00592 
00593                     // Attempt to kill orphaned process
00594                     try {
00595                         Win32Ps::kill($pid);
00596                         Log::info('Terminated orphaned process: ' . $processName . ' (PID: ' . $pid . ')');
00597                     } catch (\Exception $e) {
00598                         Log::error('Failed to terminate orphaned process ' . $processName . ': ' . $e->getMessage());
00599                     }
00600                 }
00601             }
00602 
00603             if (!$orphaned['found']) {
00604                 Log::info('No orphaned processes found');
00605             } else {
00606                 Log::warning('Found ' . count($orphaned['processes']) . ' orphaned process(es)');
00607             }
00608 
00609         } catch (\Exception $e) {
00610             Log::error('Error checking for orphaned processes: ' . $e->getMessage());
00611         }
00612 
00613         return $orphaned;
00614     }
