00625     private function generateCleanupReport($serviceVerification, $symlinkVerification, $tempCleanup, $orphanedProcesses)
00626     {
00627         $report = [
00628             'success' => true,
00629             'warnings' => [],
00630             'errors' => [],
00631             'summary' => []
00632         ];
00633 
00634         // Service verification
00635         if (!$serviceVerification['all_stopped']) {
00636             $report['success'] = false;
00637 
00638             if (!empty($serviceVerification['still_running'])) {
00639                 $report['errors'][] = 'Services still running: ' . implode(', ', $serviceVerification['still_running']);
00640             }
00641 
00642             if (!empty($serviceVerification['verification_failed'])) {
00643                 $report['warnings'][] = 'Could not verify status of: ' . implode(', ', $serviceVerification['verification_failed']);
00644             }
00645         }
00646 
00647         $report['summary'][] = 'Services checked: ' . count($serviceVerification['services']);
00648 
00649         // Symlink verification
00650         if (!$symlinkVerification['success']) {
00651             $report['warnings'][] = 'Symlinks not fully removed: ' . implode(', ', $symlinkVerification['remaining']);
00652         }
00653 
00654         // Temp file cleanup
00655         if ($tempCleanup['cleaned'] > 0) {
00656             $sizeMB = round($tempCleanup['size_freed'] / 1024 / 1024, 2);
00657             $report['summary'][] = 'Temp files cleaned: ' . $tempCleanup['cleaned'] . ' (' . $sizeMB . ' MB)';
00658         }
00659 
00660         if (!empty($tempCleanup['failed'])) {
00661             $report['warnings'][] = 'Failed to clean ' . count($tempCleanup['failed']) . ' temp file(s)';
00662         }
00663 
00664         // Orphaned processes
00665         if ($orphanedProcesses['found']) {
00666             $report['warnings'][] = 'Found ' . count($orphanedProcesses['processes']) . ' orphaned process(es)';
00667             foreach ($orphanedProcesses['processes'] as $proc) {
00668                 $report['summary'][] = 'Orphaned: ' . $proc['name'] . ' (PID: ' . $proc['pid'] . ')';
00669             }
00670         }
00671 
00672         return $report;
00673     }
