00682     private function performQuickCleanupVerification($services)
00683     {
00684         Log::info('Performing quick cleanup verification...');
00685 
00686         $startTime = microtime(true);
00687         $maxTime = 2; // Maximum 2 seconds for verification
00688 
00689         try {
00690             // Quick temp file cleanup (non-blocking)
00691             $tempCleanup = $this->cleanupTemporaryFiles();
00692 
00693             // Check if we're running out of time
00694             if (microtime(true) - $startTime > $maxTime) {
00695                 Log::debug('Cleanup verification timeout reached, skipping remaining checks');
00696                 return;
00697             }
00698 
00699             // Quick orphaned process check (non-blocking)
00700             $orphanedProcesses = $this->checkForOrphanedProcesses();
00701 
00702             // Log summary
00703             if ($tempCleanup['cleaned'] > 0) {
00704                 $sizeMB = round($tempCleanup['size_freed'] / 1024 / 1024, 2);
00705                 Log::info('Quick cleanup: ' . $tempCleanup['cleaned'] . ' temp files removed (' . $sizeMB . ' MB freed)');
00706             }
00707 
00708             if ($orphanedProcesses['found']) {
00709                 Log::info('Quick cleanup: ' . count($orphanedProcesses['processes']) . ' orphaned process(es) terminated');
00710             }
00711 
00712             $duration = round(microtime(true) - $startTime, 2);
00713             Log::info('Quick cleanup verification completed in ' . $duration . ' seconds');
00714 
00715         } catch (\Exception $e) {
00716             Log::warning('Quick cleanup verification failed: ' . $e->getMessage());
00717         }
00718     }
00719 }
